-- Original SQL captured from base 4427ae16c5dda7338e43032ac49d7c4e79b9875f; only tenant and patient binding values replaced.
SET statement_timeout=120000;
SET plan_cache_mode=force_custom_plan; PREPARE hfs1579 AS SELECT COUNT(*) FROM resources WHERE tenant_id = $1 AND resource_type = $2 AND is_deleted = FALSE AND ((id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'patient' AND ((value_reference IS NOT NULL AND split_part(value_reference, '/', -1) = $3)))) AND (id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'code-value-quantity' AND composite_group IS NOT NULL AND (value_token_system IN ($4, 'urn:x-helios:implicit code system') AND value_token_code = $5) AND (value_quantity_value > $6)))); EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default', 'Observation', '01a0d68e-81eb-7a42-975a-9c417bb5c260', 'http://loinc.org', '8302-2', '160');
